package com.forestryents;

import java.awt.Color;
import net.runelite.client.config.Alpha;
import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;
import net.runelite.client.config.ConfigSection;

@ConfigGroup("forestryents")
public interface ForestryEntsConfig extends Config
{
	@ConfigSection(
			name = "Menu Swapping",
			description = "Settings for automatic menu entry swapping",
			position = 0
	)
	String menuSection = "menu";

	@ConfigSection(
			name = "Tile Overlay",
			description = "Settings for tile highlighting",
			position = 1
	)
	String overlaySection = "overlay";

	@ConfigItem(
			keyName = "enabled",
			name = "Enable auto-swap",
			description = "Automatically swap menu entries to match the entling's requested pruning style",
			section = menuSection,
			position = 1
	)
	default boolean enabled()
	{
		return true;
	}

	@ConfigItem(
			keyName = "debugMode",
			name = "Debug mode",
			description = "Logs debug messages about prune swaps to the console",
			section = menuSection,
			position = 2
	)
	default boolean debugMode()
	{
		return false;
	}

	@ConfigItem(
			keyName = "showTileOverlay",
			name = "Show tile overlay",
			description = "Highlight entling tiles with colors based on their pruning request",
			section = overlaySection,
			position = 3
	)
	default boolean showTileOverlay()
	{
		return true;
	}

	@Alpha
	@ConfigItem(
			keyName = "backColor",
			name = "Prune-back color",
			description = "Color for entlings requesting prune-back",
			section = overlaySection,
			position = 4
	)
	default Color backColor()
	{
		return new Color(255, 0, 0, 200);
	}

	@Alpha
	@ConfigItem(
			keyName = "topColor",
			name = "Prune-top color",
			description = "Color for entlings requesting prune-top",
			section = overlaySection,
			position = 5
	)
	default Color topColor()
	{
		return new Color(0, 255, 0, 200);
	}

	@Alpha
	@ConfigItem(
			keyName = "sidesColor",
			name = "Prune-sides color",
			description = "Color for entlings requesting prune-sides",
			section = overlaySection,
			position = 6
	)
	default Color sidesColor()
	{
		return new Color(0, 150, 255, 200);
	}

	@Alpha
	@ConfigItem(
			keyName = "unknownColor",
			name = "Unknown request color",
			description = "Color for entlings with no known request",
			section = overlaySection,
			position = 8
	)
	default Color unknownColor()
	{
		return new Color(255, 255, 0, 150);
	}
}

package com.forestryents;

import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;
import java.awt.Polygon;
import java.util.Map;
import javax.inject.Inject;
import net.runelite.api.NPC;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.OverlayUtil;

class ForestryEntsOverlay extends Overlay
{
    private final ForestryEntsPlugin plugin;
    private final ForestryEntsConfig config;

    @Inject
    private ForestryEntsOverlay(ForestryEntsPlugin plugin, ForestryEntsConfig config)
    {
        this.plugin = plugin;
        this.config = config;

        setPosition(OverlayPosition.DYNAMIC);
        setLayer(OverlayLayer.ABOVE_SCENE);
    }

    @Override
    public Dimension render(Graphics2D graphics)
    {
        if (!config.showTileOverlay())
            return null;

        final Map<NPC, ForestryEntsPlugin.PruneAction> entRequests = plugin.getEntRequests();
        if (entRequests.isEmpty())
            return null;

        for (final Map.Entry<NPC, ForestryEntsPlugin.PruneAction> entry : entRequests.entrySet())
        {
            final NPC npc = entry.getKey();
            final ForestryEntsPlugin.PruneAction action = entry.getValue();

            if (npc == null || npc.getComposition() == null)
                continue;

            final Polygon tilePoly = npc.getCanvasTilePoly();
            if (tilePoly == null)
                continue;

            Color color = config.unknownColor();
            if (action != null)
                color = getColorForPruneAction(action);

            OverlayUtil.renderPolygon(graphics,
                    tilePoly,
                    color,
                    new Color(color.getRed(), color.getGreen(), color.getBlue(), 50),
                    new BasicStroke(2));
        }

        return null;
    }

    private Color getColorForPruneAction(ForestryEntsPlugin.PruneAction action)
    {
        switch (action)
        {
            case BACK:
                return config.backColor();
            case TOP:
                return config.topColor();
            case SIDES:
                return config.sidesColor();
            default:
                return config.unknownColor();
        }
    }
}

package com.forestryents;

import com.google.inject.Provides;
import java.util.HashMap;
import java.util.Map;
import javax.inject.Inject;
import lombok.Getter;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.Menu;
import net.runelite.api.MenuAction;
import net.runelite.api.MenuEntry;
import net.runelite.api.NPC;
import net.runelite.api.events.GameTick;
import net.runelite.api.events.NpcDespawned;
import net.runelite.api.events.NpcSpawned;
import net.runelite.api.events.PostMenuSort;
import net.runelite.api.gameval.NpcID;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.overlay.OverlayManager;
import net.runelite.client.util.Text;

@Slf4j
@PluginDescriptor(
		name = "Friendly Ent Helper",
		description = "Automatically swaps menu entries for Friendly Ent pruning based on their overhead text",
		tags = {"forestry", "ent", "prune", "menu", "swap", "woodcutting"}
)
public class ForestryEntsPlugin extends Plugin
{
	@Getter
    public enum PruneAction
	{
		BACK("prune-back"),
		TOP("prune-top"),
		SIDES("prune-sides");

		private final String option;

		PruneAction(String option)
		{
			this.option = option;
		}

    }

	@Inject
	private Client client;

	@Inject
	private ForestryEntsConfig config;

	@Inject
	private OverlayManager overlayManager;

	@Inject
	private ForestryEntsOverlay overlay;

	@Getter
	private final Map<NPC, PruneAction> entRequests = new HashMap<>();

	@Provides
	ForestryEntsConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(ForestryEntsConfig.class);
	}

	@Override
	protected void startUp()
	{
		overlayManager.add(overlay);
	}

	@Override
	protected void shutDown()
	{
		overlayManager.remove(overlay);
		entRequests.clear();
	}

	@Subscribe
	public void onNpcSpawned(NpcSpawned npcSpawned)
	{
		NPC npc = npcSpawned.getNpc();
		if (npc.getId() == NpcID.GATHERING_EVENT_ENTLINGS_NPC_01)
			entRequests.put(npc, null);
	}

	@Subscribe
	public void onGameTick(GameTick gameTick)
	{
		if (!config.enabled())
			return;

		if (entRequests.isEmpty())
			return;

		for (NPC npc : entRequests.keySet())
		{
			String overheadText = npc.getOverheadText();
			if (overheadText == null || overheadText.isEmpty())
				continue;

			String normalizedText = Text.removeTags(overheadText).toLowerCase();
			PruneAction desiredPrune = determineDesiredPrune(normalizedText);

			if (desiredPrune == null)
				continue;

			entRequests.put(npc, desiredPrune);

			if (config.debugMode())
				log.debug("Cached entling request: NPC {} wants {}", npc.getIndex(), desiredPrune);
		}
	}

	@Subscribe
	public void onNpcDespawned(NpcDespawned npcDespawned)
	{
		// Clean up when entlings despawn
		NPC npc = npcDespawned.getNpc();
		if (npc.getId() == NpcID.GATHERING_EVENT_ENTLINGS_NPC_01
				|| npc.getId() == NpcID.GATHERING_EVENT_ENTLINGS_NPC_01_PRUNED)
			entRequests.remove(npc);
	}

	@Subscribe
	public void onPostMenuSort(PostMenuSort postMenuSort)
	{
		if (!config.enabled() || client.isMenuOpen())
			return;

		Menu menu = client.getMenu();
		MenuEntry[] menuEntries = menu.getMenuEntries();

		if (menuEntries.length == 0)
			return;

		MenuEntry topEntry = menuEntries[menuEntries.length - 1];

		if (topEntry.getType() != MenuAction.NPC_FIRST_OPTION &&
				topEntry.getType() != MenuAction.NPC_SECOND_OPTION &&
				topEntry.getType() != MenuAction.NPC_THIRD_OPTION &&
				topEntry.getType() != MenuAction.NPC_FOURTH_OPTION &&
				topEntry.getType() != MenuAction.NPC_FIFTH_OPTION)
			return;

		NPC npc = topEntry.getNpc();
		if (npc == null)
			return;

		int npcId = npc.getId();
		if (npcId != NpcID.GATHERING_EVENT_ENTLINGS_NPC_01)
			return;

		PruneAction desiredPrune = entRequests.get(npc);
		if (desiredPrune == null)
			return;

		swapEntPrune(menu, menuEntries, desiredPrune, npc);
	}

	/**
	 * Determines which pruning option the entling wants based on their overhead text
	 * returns the prune option to prioritize (or null if no specific priority needed)
	 *
	 * Although there can be more than 1 option (Top & Back) you can onle do the 1 meyn option
	 * Maybe we should quee the menu options so whent hey finish with back we dont have to wait for overhead...
	 * Problem for another day I reckon
	 */
	private PruneAction determineDesiredPrune(String overheadText)
	{
		if (overheadText.contains("breezy") && overheadText.contains("back"))
			return PruneAction.BACK;

		else if (overheadText.contains("leafy") && overheadText.contains("mullet"))
			return PruneAction.TOP;

		else if (overheadText.contains("short") && overheadText.contains("back") && overheadText.contains("sides"))
			return PruneAction.BACK;

		else if (overheadText.contains("short") && overheadText.contains("top"))
			return PruneAction.TOP;

		return null;
	}

	private void swapEntPrune(Menu menu, MenuEntry[] entries, PruneAction desiredPrune, NPC npc)
	{
		int desiredIndex = -1;
		int topIndex = -1;

		for (int i = 0; i < entries.length; i++)
		{
			MenuEntry entry = entries[i];

			if (entry.getNpc() != npc)
				continue;

			if (topIndex < i)
				topIndex = i;

			String option = Text.removeTags(entry.getOption()).toLowerCase();

			if (config.debugMode())
				log.debug("Checking menu option: {} against desired: {}", option, desiredPrune.getOption());

			if (option.equals(desiredPrune.getOption()))
				desiredIndex = i;
		}

		if (desiredIndex < 0 || desiredIndex == topIndex) {
			if (config.debugMode())
				log.debug("Failed to find desired prune option: {}", desiredPrune.getOption());
			return;
		}

		swap(menu, entries, desiredIndex, topIndex);

		if (config.debugMode())
			log.debug("Swapped Entling prune: {} (index {} -> {})", desiredPrune.getOption(), desiredIndex, topIndex);
	}

	private void swap(Menu menu, MenuEntry[] entries, int index1, int index2)
	{
		MenuEntry entry1 = entries[index1];
		MenuEntry entry2 = entries[index2];

		entries[index1] = entry2;
		entries[index2] = entry1;

		menu.setMenuEntries(entries);
	}
}

